local b64chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local b64invchars = {}
for i = 1, #b64chars do
    b64invchars[b64chars:sub(i,i)] = i - 1
end

local function base64_decode(data)
    data = data:gsub("[^"..b64chars.."=]", "") -- Remove invalid characters
    local result = ""
    local padding = data:match("(=*)$") or ""
    data = data:gsub("=+$", "") -- Remove padding for decoding
    local len = #data

    for i = 1, len, 4 do
        local c1 = b64invchars[data:sub(i,i)]
        local c2 = b64invchars[data:sub(i+1,i+1)]
        local c3 = b64invchars[data:sub(i+2,i+2)]
        local c4 = b64invchars[data:sub(i+3,i+3)]

        local n = (c1 << 18) + (c2 << 12) + (c3 << 6) + c4

        local byte1 = (n >> 16) & 0xFF
        local byte2 = (n >> 8) & 0xFF
        local byte3 = n & 0xFF

        result = result .. string.char(byte1)
        if c3 ~= nil then result = result .. string.char(byte2) end
        if c4 ~= nil then result = result .. string.char(byte3) end
    end
    -- Handle padding
    if padding == "=" then
        return result:sub(1, #result - 2)
    elseif padding == "==" then
        return result:sub(1, #result - 1)
    end
    return result
end
-- --- End Base64 Decoding Function ---

-- --- Main Script Logic ---

-- 1. PASTE YOUR BASE64 STRING HERE
-- IMPORTANT: Replace "YOUR_BASE64_STRING_GOES_HERE" with the actual Base64 data
-- from your input.txt file. If it's very long, you might need to split it
-- into multiple lines or chunk it, though a single long string is often fine.
local base64Data = "" -- <--- PASTE YOUR BASE64 DATA HERE!

-- 2. Find the speaker peripheral
local speaker = peripheral.find("speaker")
if not speaker then
    print("Error: No speaker found! Make sure it's placed next to the computer/turtle.")
    return
end

-- 3. Define the output file path for the decoded DFPWM
local decodedDfPwmFile = "embedded_audio.dfpwm" -- Name for the temporary decoded file

if #base64Data == 0 or base64Data == "YOUR_BASE64_STRING_GOES_HERE" then
    print("Error: Base64 data is missing or not pasted into the script.")
    print("Please edit this script and paste your Base64 string into the 'base64Data' variable.")
    return
end

-- 4. Decode the Base64 string to binary DFPWM data
print("Decoding Base64 data...")
local dfpwmBinaryData = base64_decode(base64Data)

if not dfpwmBinaryData or #dfpwmBinaryData == 0 then
    print("Error: Failed to decode Base64 data or decoded data is empty.")
    return
end

-- 5. Save the decoded binary data to a new .dfpwm file
print("Saving decoded DFPWM data to " .. decodedDfPwmFile .. "...")
local outFileHandle, err = fs.open(decodedDfPwmFile, "wb") -- Open in binary write mode
if not outFileHandle then
    print("Error opening " .. decodedDfPwmFile .. " for writing: " .. err)
    return
end
outFileHandle.write(dfpwmBinaryData)
outFileHandle.close()
print("DFPWM file created successfully.")

-- 6. Play the DFPWM audio
print("Playing " .. decodedDfPwmFile .. "...")

local dfpwm = require("cc.audio.dfpwm")
local decoder = dfpwm.make_decoder()
local audioFileHandle, err = fs.open(decodedDfPwmFile, "rb") -- Open in binary read mode
if not audioFileHandle then
    print("Error opening " .. decodedDfPwmFile .. " for playback: " .. err)
    return
end

local chunkSize = 16 * 1024 -- 16KB per chunk, optimal for DFPWM streaming

while true do
    local chunk = audioFileHandle.read(chunkSize)
    if not chunk then
        break -- End of file
    end

    local buffer = decoder(chunk)
    while not speaker.playAudio(buffer) do
        -- Speaker buffer is full, wait for it to empty
        os.pullEvent("speaker_audio_empty")
    end
end

audioFileHandle.close()
print("Finished playing audio.")